head.script:
scwin.screenId = "jldfil71202";

///////// 1. 변수 및 선언 영역 /////////

scwin.expDateFmt = undefined;

// as-is 흐름 보존 — 스켈레톤이 대체한 함수가 쓰던 전역 선언
scwin.form = undefined;


///////// 2. 초기화 영역 /////////

// 속성 EL 실현 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_attrReals
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_attrReals = async function () {
    const attrRealsList = [{ childId: "__rb23", attr: "label", fn: function () { return String(dma_readDataVO.get("lpHdQty")); } }];
    const root = (function () { try { const f = $c.win.getFrame(); return (f && f.render) ? f.render : null; } catch (e) { return null; } })();
    const hasText = function (t) { return /[가-힣A-Za-z0-9]/.test(String(t == null ? "" : t)); };
    let applied = 0;
    for (let i = 0; i < attrRealsList.length; i++) {
        const a = attrRealsList[i];
        const comp = $c.util.getComponent(a.childId);
        const el = (comp && comp.getID && root) ? root.querySelector("#" + comp.getID()) : null;
        if (!comp && !el) { console.warn("[sdd] 속성 실현 대상 부재: " + a.childId); continue; }
        let v;
        try { v = a.fn(); } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId + "." + a.attr }); continue; }
        if (a.attr === "style") {
            if (comp && typeof comp.setStyle === "function") {
                const decls = String(v).split(";");
                for (let di = 0; di < decls.length; di++) {
                    const kv = decls[di].split(":");
                    if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
                }
            } else if (el) { el.style.cssText = (el.style.cssText || "") + ";" + v; }
        } else if (a.attr === "label") {
            if (comp && typeof comp.setValue === "function") { comp.setValue(v); } else if (el) { el.textContent = v; }
        } else if (a.attr === "__value") {
            if (comp && typeof comp.setValue === "function") { comp.setValue(v); }
        } else if (a.attr === "__items") {
            if (comp && typeof comp.addItem === "function" && v && v.length) {
                let hasVal = false;
                for (let ii = 0; ii < v.length; ii++) { if (hasText(v[ii][0]) || hasText(v[ii][1])) { hasVal = true; break; } }
                if (hasVal) {
                    if (typeof comp.removeAll === "function") { comp.removeAll(); }
                    for (let ij = 0; ij < v.length; ij++) {
                        const lb = String(v[ij][1] || "");
                        comp.addItem(String(v[ij][0] || ""), hasText(lb) ? lb : "");
                    }
                }
            }
        } else if (a.attr === "class") {
            if (el) { el.className = v; }
        } else if (a.attr === "__html") {
            if (el && !el.querySelector('[class*="w2"], input, select, textarea, button')) { el.innerHTML = v; }
        } else if (el) {
            el.setAttribute(a.attr, v);
            if (a.attr === "src" && el.tagName === "IMG") { el.src = v; }
        }
        applied++;
    }
    return applied;
};

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "if_listBzTpCd", fn: function(){ return ((dma_readDataVO.get("listBzTpCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listBzTpCd"); })()) === '701'); } }, { id: "tr_87", fn: function(){ return ((dma_readDataVO.get("listBzTpCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listBzTpCd"); })()) === '701'); } }, { id: "tr_99", fn: function(){ return ((dma_readDataVO.get("listBzTpCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listBzTpCd"); })()) === '701'); } }, { id: "tr_104", fn: function(){ return ((dma_readDataVO.get("listBzTpCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listBzTpCd"); })()) === '701'); } }, { id: "if_listBzTpCd_2", fn: function(){ return ((dma_readDataVO.get("listBzTpCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listBzTpCd"); })()) === '702'); } }, { id: "tr_117", fn: function(){ return ((dma_readDataVO.get("listBzTpCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listBzTpCd"); })()) === '702'); } }, { id: "tr_131", fn: function(){ return ((dma_readDataVO.get("listBzTpCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listBzTpCd"); })()) === '702'); } }, { id: "tr_140", fn: function(){ return ((dma_readDataVO.get("listBzTpCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listBzTpCd"); })()) === '702'); } }, { id: "if_listBzTpCd_3", fn: function(){ return ((dma_readDataVO.get("listBzTpCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listBzTpCd"); })()) === '703'); } }, { id: "tr_153", fn: function(){ return ((dma_readDataVO.get("listBzTpCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listBzTpCd"); })()) === '703'); } }, { id: "tr_165", fn: function(){ return ((dma_readDataVO.get("listBzTpCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listBzTpCd"); })()) === '703'); } }, { id: "if_listBzTpCd_4", fn: function(){ return ((dma_readDataVO.get("listBzTpCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listBzTpCd"); })()) === '704'); } }, { id: "tr_173", fn: function(){ return ((dma_readDataVO.get("listBzTpCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listBzTpCd"); })()) === '704'); } }, { id: "tr_185", fn: function(){ return ((dma_readDataVO.get("listBzTpCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listBzTpCd"); })()) === '704'); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// [A] 초기 목록 미해결 — jldfil71202: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_attrReals();
        await scwin.init_conds();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil71202.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @method
 * @name scwin.btn_Search_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_Search_onclick = async function(e){
    const ev = e;
    const event = ev;
    const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
    /* sdd-asis-lifecycle:begin btn_Search_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    await scwin.search()
    /* sdd-asis-lifecycle:end */
};

/**
 * @event
 * @name scwin.__ev_2_btn_Search_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.__ev_2_btn_Search_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin __ev_2_btn_Search_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.search()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil71202.__ev_2_btn_Search_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_EtnChangePage
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_EtnChangePage = async function () {
    const sbmOptions = {
        id: "tx_fn_EtnChangePage",
        method: "post",
        action: "/etn/LossLimitEtnList.do",
        ref: "dma_EtnChangePageReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil71202.tx_fn_EtnChangePage" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_Search
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_Search = async function () {
    const sbmOptions = {
        id: "tx_fn_Search",
        method: "post",
        action: "/etn/EtnList.do",
        ref: "dma_SearchReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil71202.tx_fn_Search" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.etnChangePage
 * @author Inswave
 * @date 2026. 09. 29
 * @param tab
 * @returns
 * @hidden N
*/
scwin.etnChangePage = async function (tab) {
    /* sdd-asis-lifecycle:begin fn_EtnChangePage — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.form = (document.etnListForm || { elements: [] });
    const lastSaveStatCdInt = parseInt($c.util.getComponent('dma_EtnChangePageReq').get('lastSaveStatCd'));
    if (tab == 1) {
        return;
    } else {
        if (tab == 2) {
            $c.util.getComponent('dma_EtnChangePageReq').set('method', 'lossLimitViewIsuTab2');
        } else {
            if (tab == 3) {
                $c.util.getComponent('dma_EtnChangePageReq').set('method', 'lossLimitViewIsurTab');
            } else {
                if (tab == 4) {
                    $c.util.getComponent('dma_EtnChangePageReq').set('method', 'lossLimitViewSrtyLpTab');
                } else {
                    $c.util.getComponent('dma_EtnChangePageReq').set('method', 'lossLimitViewAttachFileTab');
                }
            }
        }
    }
    scwin.form.action = 'LossLimitEtnList.do';
    await scwin.tx_fn_EtnChangePage();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.search = async function () {
    /* sdd-asis-lifecycle:begin fn_Search — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.form = (document.etnListForm || { elements: [] });
    scwin.form.action = "EtnList.do";
    $c.util.getComponent('dma_EtnChangePageReq').set('listBzTpCd', "");
    $c.util.getComponent('dma_EtnChangePageReq').set('method', 'searchList');
    await scwin.tx_fn_Search();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init = function () {
    /* sdd-asis-lifecycle:begin fn_init — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.cal();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.cal
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.cal = function () {
    /* sdd-asis-lifecycle:begin fn_cal — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('txt_declSpd').setLabel($c.num.formatNumber(String($c.util.getComponent('txt_declSpd').getValue())));
    /* sdd-asis-lifecycle:end */
};
